29	 * hotbar): non-empty slots are packed in order, stackable items merge into
30	 * earlier stacks, and anything that still overflows 36 slots is dropped.
31	 */
32	/** Coerces a persisted hotbar index to a finite integer within 0..HOTBAR_SLOTS-1. */
33	function normalizeSelectedSlot(value: number): number {
34	  const index = Number.isFinite(value) ? Math.floor(value) : 0;
35	  return Math.max(0, Math.min(HOTBAR_SLOTS - 1, index));
36	}
