38	export function migrateSaveV1toV2(save: SaveDataV1): SaveDataV2 {
39	  const migrated: SaveDataV2 = { ...save, version: 2, selectedSlot: normalizeSelectedSlot(save.selectedSlot) };
40	
41	  if (Array.isArray(save.inventorySlots)) {
42	    const packed: Array<{ id: string | null; count: number; durability?: number }> = [];
43	    for (const saved of save.inventorySlots) {
44	      if (!saved?.id || saved.count <= 0) continue;
45	      // Items without durability stack; merge them into an earlier stack first.
46	      const stackable = ITEM_DEF_BY_ID[saved.id] ? !ITEM_DEF_BY_ID[saved.id].maxDurability : false;
47	      let remaining = saved.count;
48	      if (stackable) {
49	        for (const slot of packed) {
50	          if (slot.id !== saved.id || slot.count >= MAX_STACK_SIZE) continue;
51	          const moved = Math.min(MAX_STACK_SIZE - slot.count, remaining);
52	          slot.count += moved;
53	          remaining -= moved;
54	          if (remaining === 0) break;
55	        }
56	      }
57	      while (remaining > 0 && packed.length < INVENTORY_SLOTS) {
58	        const moved = Math.min(maxStackSizeForItem(saved.id), remaining);
59	        packed.push({ id: saved.id, count: moved, durability: saved.durability });
60	        remaining -= moved;
61	      }
62	    }
63	    migrated.inventorySlots = packed;
64	  }
65	
66	  return migrated;
67	}
